from django.shortcuts import render
from transaction.models import *
from transaction.utils import *
from register.models import *
from django.http import HttpResponse, HttpResponseRedirect, HttpResponseForbidden
from django.contrib.auth.decorators import login_required
from django.contrib.auth.models import User

@login_required
def index(request):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	if request.method == 'POST':
		if 'user_id' in request.session:
			user_id=User.objects.get(id=request.session.get('user_id')).id
		else:
			user_id=False
		if 'k_id' in request.POST:
			k_id=request.POST['k_id']
			if k_id:
				j=Register.objects.get(k_id=k_id)
				Transaction.objects.create(tdate=datetime.now(), register_id=j.id, level=Level(j.k_id), service=service_chk(j.id), status=InOut(j.id), user_id=user_id)
				Register.objects.filter(id=j.id).update(log=datetime.now())
				l=Transaction.objects.filter(register_id=j.id).last()
				tdate=l.tdate
				k={'1':'IN', '0':'OUT'}
				o=k[l.status]
				lev=Level(j.k_id)
				service=l.service
				return render(request, 'transaction/index.html', {'l':l, 'o':o, 'lev':lev, 'tdate':tdate, 'service':service}, content_type='text/html')
			else:
				return HttpResponse("Does not Exist")
	return render(request, 'transaction/index.html', {'nxtgnuser':nxtgnuser}, content_type='text/html') 

